template.query:
query GetTableAttributeTypes($tableId: ID, $tableIdentifier: String) {
  table: tableByIdentifier(identifier: $tableIdentifier) {
    id
    identifier
    description
    attributes {
      id
      identifier
      name
      attributeType {
        id
        identifier
        name
        dataType
        format
      }
    }
    attributeTypes {
      id
      identifier
      name
      description
      dataType
      format
      constraints
      defaultValue
      createdAt
    }
    attributeCount
  }
}
